import React, { useState, useEffect, useRef } from 'react';
import './Time_Widget.css';

const TimeWidget = ({ isVisible, onClose, onTimeQuery }) => {
    const [currentTime, setCurrentTime] = useState(new Date());
    const [location, setLocation] = useState('Loading...');
    const [widgetSize, setWidgetSize] = useState('normal');
    const [isDragging, setIsDragging] = useState(false);
    const [isResizing, setIsResizing] = useState(false);
    const [position, setPosition] = useState({ x: window.innerWidth - 300, y: 100 });
    const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
    const [size, setSize] = useState({ width: 200, height: 150 });

    const widgetRef = useRef(null);
    const dragStartRef = useRef({ x: 0, y: 0 });

    // Update time every second
    useEffect(() => {
        const timer = setInterval(() => {
            setCurrentTime(new Date());
        }, 1000);

        return () => clearInterval(timer);
    }, []);

    // Get location (simplified - in real app would use geolocation API)
    useEffect(() => {
        // For demo purposes, set a default location
        // In production, this would use navigator.geolocation
        setLocation('New York, NY');
    }, []);

    // Format time for display
    const formatTime = (date) => {
        return date.toLocaleTimeString('en-US', {
            hour12: true,
            hour: 'numeric',
            minute: '2-digit',
            second: '2-digit'
        });
    };

    // Format date for display
    const formatDate = (date) => {
        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    };

    // Handle mouse down for dragging
    const handleMouseDown = (e) => {
        if (e.target.closest('.widget-controls') || e.target.closest('.resize-handle')) {
            return; // Don't drag if clicking controls or resize handle
        }

        setIsDragging(true);
        dragStartRef.current = {
            x: e.clientX - position.x,
            y: e.clientY - position.y
        };
        document.body.style.cursor = 'grabbing';
    };

    // Handle mouse move for dragging and resizing
    const handleMouseMove = (e) => {
        if (isDragging) {
            setPosition({
                x: e.clientX - dragStartRef.current.x,
                y: e.clientY - dragStartRef.current.y
            });
        } else if (isResizing) {
            const newWidth = Math.max(150, e.clientX - position.x);
            const newHeight = Math.max(100, e.clientY - position.y);
            setSize({ width: newWidth, height: newHeight });
        }
    };

    // Handle mouse up
    const handleMouseUp = () => {
        setIsDragging(false);
        setIsResizing(false);
        document.body.style.cursor = 'default';
    };

    // Add global mouse event listeners
    useEffect(() => {
        if (isDragging || isResizing) {
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        }

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, isResizing]);

    // Handle resize start
    const handleResizeStart = (e) => {
        e.stopPropagation();
        setIsResizing(true);
        document.body.style.cursor = 'se-resize';
    };

    // Size control functions
    const increaseWidgetSize = () => {
        const sizes = ['small', 'normal', 'large', 'xlarge'];
        const currentIndex = sizes.indexOf(widgetSize);
        if (currentIndex < sizes.length - 1) {
            setWidgetSize(sizes[currentIndex + 1]);
        }
    };

    const decreaseWidgetSize = () => {
        const sizes = ['small', 'normal', 'large', 'xlarge'];
        const currentIndex = sizes.indexOf(widgetSize);
        if (currentIndex > 0) {
            setWidgetSize(sizes[currentIndex - 1]);
        }
    };

    const hideTimeDisplay = () => {
        onClose();
    };

    // Sample contacts data
    const contacts = [
        { name: 'Alice Johnson', status: 'Available' },
        { name: 'Bob Smith', status: 'Busy' },
        { name: 'Carol Davis', status: 'Away' }
    ];

    if (!isVisible) return null;

    return (
        <div
            ref={widgetRef}
            className={`time-widget widget-size-${widgetSize} ${isDragging ? 'widget-dragging' : ''} ${isResizing ? 'widget-resizing' : ''}`}
            style={{
                left: position.x,
                top: position.y,
                width: size.width,
                height: size.height,
                cursor: isDragging ? 'grabbing' : 'grab'
            }}
            onMouseDown={handleMouseDown}
        >
            {/* Corner brackets */}
            <div className="corner-top-right"></div>
            <div className="corner-bottom-left"></div>

            {/* Widget Controls */}
            <div className="widget-controls">
                <button
                    className="widget-control-btn"
                    onClick={decreaseWidgetSize}
                    title="Decrease Size"
                >
                    -
                </button>
                <button
                    className="widget-control-btn"
                    onClick={increaseWidgetSize}
                    title="Increase Size"
                >
                    +
                </button>
                <button
                    className="widget-control-btn"
                    onClick={hideTimeDisplay}
                    title="Close"
                >
                    ×
                </button>
            </div>

            {/* Time Display */}
            <div className="time-label">CURRENT TIME</div>
            <div className="time-value">{formatTime(currentTime)}</div>
            <div className="time-location">{location}</div>

            {/* Date Display */}
            <div style={{
                fontSize: '10px',
                color: 'rgba(255, 255, 255, 0.6)',
                textAlign: 'center',
                marginTop: '4px',
                fontWeight: '400'
            }}>
                {formatDate(currentTime)}
            </div>

            {/* Contacts Section */}
            <div className="time-contacts">
                <div className="contacts-label">CONTACTS</div>
                <div className="contacts-list">
                    {contacts.map((contact, index) => (
                        <div key={index} className="contact-item">
                            <span className="contact-name">{contact.name}</span>
                            <span className="contact-status">{contact.status}</span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Resize Handle */}
            <div
                className="resize-handle"
                onMouseDown={handleResizeStart}
            ></div>
        </div>
    );
};

export default TimeWidget;
